import{_ as e,a0 as p,w as a,s as N,ao as s,I as r,x as l,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"為什麼排序的複雜度為 O(N log N) | LCTT x X-CMD","titleTemplate":false,"description":"為什麼排序的複雜度為 O(N log N) | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼排序的複雜度為 O(N log N) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼排序的複雜度為 O(N log N) | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20190105 Why Sorting is O(N log N)","title":"為什麼排序的複雜度為 O(N log N)","tag":"202009","desc":""},"relativePath":"202009/20190105 Why Sorting is O(N log N).md","filePath":"[post].md"}'),$={name:"202009/20190105 Why Sorting is O(N log N).md"};function g(d,t,u,m,f,T){const o=p("Link");return a(),N("div",null,[t[32]||(t[32]=s('<h1 id="為什麼排序的複雜度為-o-n-log-n" tabindex="-1">為什麼排序的複雜度為 O(N log N) <a class="header-anchor" href="#為什麼排序的複雜度為-o-n-log-n" aria-label="Permalink to “為什麼排序的複雜度為 O(N log N)”">​</a></h1><p>基本上所有正而八經的算法教材都會解釋像<ruby>快速排序<rt>quicksort</rt></ruby>和<ruby>堆排序<rt>heapsort</rt></ruby>這樣的排序算法有多快，但並不需要複雜的數學就能證明你可以逐漸趨近的速度有多快。</p><blockquote><p>關於標記的一個嚴肅説明：</p><p>大多數計算機專業的科學家使用大寫字母 O 標記來指代“趨近，直到到達一個常數比例因子”，這與數學專業所指代的意義是有所區別的。這裏我使用的大 O 標記的含義與計算機教材所指相同，但至少不會和其他數學符號混用。</p></blockquote><h3 id="基於比較的排序" tabindex="-1">基於比較的排序 <a class="header-anchor" href="#基於比較的排序" aria-label="Permalink to “基於比較的排序”">​</a></h3><p>先來看個特例，即每次比較兩個值大小的算法（快速排序、堆排序，及其它通用排序算法）。這種思想後續可以擴展至所有排序算法。</p><h4 id="一個簡單的最差情況下的計數角度" tabindex="-1">一個簡單的最差情況下的計數角度 <a class="header-anchor" href="#一個簡單的最差情況下的計數角度" aria-label="Permalink to “一個簡單的最差情況下的計數角度”">​</a></h4><p>假設有 4 個互不相等的數，且順序隨機，那麼，可以通過只比較一對數字完成排序嗎？顯然不能，證明如下：根據定義，要對該數組排序，需要按照某種順序重新排列數字。換句話説，你需要知道用哪種排列方式？有多少種可能的排列？第一個數字可以放在四個位置中的任意一個，第二個數字可以放在剩下三個位置中的任意一個，第三個數字可以放在剩下兩個位置中的任意一個，最後一個數字只有剩下的一個位置可選。這樣，共有 $4×3×2×1 = 4! = 24$ 種排列可供選擇。通過一次比較大小，只能產生兩種可能的結果。如果列出所有的排列，那麼“從小到大”排序對應的可能是第 8 種排列，按“從大到小”排序對應的可能是第 24 種排列，但無法知道什麼時候需要的是其它 22 種排列。</p><p>通過 2 次比較，可以得到 2×2=4 種可能的結果，這仍然不夠。只要比較的次數少於 5（對應 $2^{5} = 32$ 種輸出），就無法完成 4 個隨機次序的數字的排序。如果 $W(N)$ 是最差情況下對 $N$ 個不同元素進行排序所需要的比較次數，那麼，</p><p>$$ 2^{W(N)} \\geq N! $$</p><p>兩邊取以 2 為底的對數，得：</p><p>$$ W(N) \\geq \\log_{2}{N!} $$</p>',11)),r("p",null,[t[1]||(t[1]=l("$N!$ 的增長近似於 $N^{N}$ （參閲 ",-1)),i(o,{href:"http://hyperphysics.phy-astr.gsu.edu/hbase/Math/stirling.html"},{default:n(()=>[...t[0]||(t[0]=[l("Stirling 公式",-1)])]),_:1}),t[2]||(t[2]=l("），那麼，",-1))]),t[33]||(t[33]=s('<p>$$ W(N) \\succeq \\log N^{N} = N\\log N $$</p><p>這就是最差情況下從輸出計數的角度得出的 $O(N\\log N)$ 上限。</p><h4 id="從信息論角度的平均狀態的例子" tabindex="-1">從信息論角度的平均狀態的例子 <a class="header-anchor" href="#從信息論角度的平均狀態的例子" aria-label="Permalink to “從信息論角度的平均狀態的例子”">​</a></h4><p>使用一些信息論知識，就可以從上面的討論中得到一個更有力的結論。下面，使用排序算法作為信息傳輸的編碼器：</p><ol><li>任取一個數，比如 15</li><li>從 4 個數字的排列列表中查找第 15 種排列</li><li>對這種排列運行排序算法，記錄所有的“大”、“小”比較結果</li><li>用二進制編碼發送比較結果</li><li>接收端重新逐步執行發送端的排序算法，需要的話可以引用發送端的比較結果</li><li>現在接收端就可以知道發送端如何重新排列數字以按照需要排序，接收端可以對排列進行逆算，得到 4 個數字的初始順序</li><li>接收端在排列表中檢索發送端的原始排列，指出發送端發送的是 15</li></ol>',5)),r("p",null,[t[4]||(t[4]=l("確實，這有點奇怪，但確實可以。這意味着排序算法遵循着與編碼方案相同的定律，包括理論所證明的不存在通用的數據壓縮算法。算法中每次比較發送 1 比特的比較結果編碼數據，根據信息論，比較的次數至少是能表示所有數據的二進制位數。更技術語言點，",-1)),i(o,{href:"https://en.wikipedia.org/wiki/Shannon%27s_source_coding_theorem"},{default:n(()=>[...t[3]||(t[3]=[l("平均所需的最小比較次數是輸入數據的香農熵，以比特為單位",-1)])]),_:1}),t[5]||(t[5]=l("。熵是衡量信息等不可預測量的數學度量。",-1))]),t[34]||(t[34]=r("p",null,"包含 $N$ 個元素的數組，元素次序隨機且無偏時的熵最大，其值為 $\\log_{2}{N!}$ 個比特。這證明 $O(N\\log N)$ 是一個基於比較的對任意輸入排序的最優平均值。",-1)),r("p",null,[t[7]||(t[7]=l("以上都是理論説法，那麼實際的排序算法如何做比較的呢？下面是一個數組排序所需比較次數均值的圖。我比較的是理論值與快速排序及 ",-1)),i(o,{href:"https://en.wikipedia.org/wiki/Merge-insertion_sort"},{default:n(()=>[...t[6]||(t[6]=[l("Ford-Johnson 合併插入排序",-1)])]),_:1}),t[8]||(t[8]=l(" 的表現。後者設計目的就是最小化比較次數（整體上沒比快速排序快多少，因為生活中相對於最大限度減少比較次數，還有更重要的事情）。又因為",-1)),t[9]||(t[9]=r("ruby",null,[l("合併插入排序"),r("rt",null,"merge-insertion sort")],-1)),t[10]||(t[10]=l("是在 1959 年提出的，它一直在調整，以減少了一些比較次數，但圖示説明，它基本上達到了最優狀態。",-1))]),t[35]||(t[35]=s('<p><img src="https://theartofmachinery.com/images/sorting_is_nlogn/sorting_algorithms_num_comparisons.svg" alt="隨機排列 100 個元素所需的平均排序次數圖。最下面的線是理論值，約 1% 處的是合併插入算法，原始 quicksort 大約在 25% 處。"></p><p>一點點理論導出這麼實用的結論，這感覺真棒！</p><h4 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h4><p>證明了：</p><ol><li>如果數組可以是任意順序，在最壞情況下至少需要 $O(N\\log N)$ 次比較。</li><li>數組的平均比較次數最少是數組的熵，對隨機輸入而言，其值是 $O(N\\log N)$ 。</li></ol><p>注意，第 2 個結論允許基於比較的算法優於 $O(N\\log N)$，前提是輸入是低熵的（換言之，是部分可預測的）。如果輸入包含很多有序的子序列，那麼合併排序的性能接近 $O(N)$。如果在確定一個位之前，其輸入是有序的，插入排序性能接近 $O(N)$。在最差情況下，以上算法的性能表現都不超出 $O(N\\log N)$。</p><h3 id="一般排序算法" tabindex="-1">一般排序算法 <a class="header-anchor" href="#一般排序算法" aria-label="Permalink to “一般排序算法”">​</a></h3>',7)),r("p",null,[t[12]||(t[12]=l("基於比較的排序在實踐中是個有趣的特例，但從理論上講，計算機的 ",-1)),i(o,{href:"https://c9x.me/x86/html/file_module_x86_id_35.html"},{default:n(()=>[...t[11]||(t[11]=[l("CMP",-1)])]),_:1}),t[13]||(t[13]=l(" 指令與其它指令相比，並沒有什麼特別之處。在下面兩條的基礎上，前面兩種情形都可以擴展至任意排序算法：",-1))]),t[36]||(t[36]=s('<ol><li>大多數計算機指令有多於兩個的輸出，但輸出的數量仍然是有限的。</li><li>一條指令有限的輸出意味着一條指令只能處理有限的熵。</li></ol><p>這給出了 $O(N\\log N)$ 對應的指令下限。任何物理上可實現的計算機都只能在給定時間內執行有限數量的指令，所以算法的執行時間也有對應 $O(N\\log N)$ 的下限。</p><h4 id="什麼是更快的算法" tabindex="-1">什麼是更快的算法？ <a class="header-anchor" href="#什麼是更快的算法" aria-label="Permalink to “什麼是更快的算法？”">​</a></h4><p>一般意義上的 $O(N\\log N)$ 下限，放在實踐中來看，如果聽人説到任何更快的算法，你要知道，它肯定以某種方式“作弊”了，其中肯定有圈套，即它不是一個可以處理任意大數組的通用排序算法。可能它是一個有用的算法，但最好看明白它字裏行間隱含的東西。</p><p>一個廣為人知的例子是<ruby>基數排序<rt>radix sort</rt></ruby>算法，它經常被稱為 $O(N)$ 排序算法，但它只能處理所有數字都能放入 $k$ 比特的情況，所以實際上它的性能是 $O({kN})$。</p><p>什麼意思呢？假如你用的 8 位計算機，那麼 8 個二進制位可以表示 $2^{8} = 256$ 個不同的數字，如果數組有上千個數字，那麼其中必有重複。對有些應用而言這是可以的，但對有些應用就必須用 16 個二進制位來表示，16 個二進制位可以表示 $2^{16} = 65,536$ 個不同的數字。32 個二進制位可以表示 $2^{32} = 4,294,967,296$ 不同的數字。隨着數組長度的增長，所需要的二進制位數也在增長。要表示 $N$ 個不同的數字，需要 $k \\geq \\log_{2}N$ 個二進制位。所以，只有允許數組中存在重複的數字時，$O({kN})$ 才優於 $O(N\\log N)$。</p>',6)),r("p",null,[t[15]||(t[15]=l("一般意義上輸入數據的 $O(N\\log N)$ 的性能已經説明了全部問題。這個討論不那麼有趣因為很少需要在 32 位計算機上對幾十億整數進行排序，",-1)),i(o,{href:"https://sortbenchmark.org/"},{default:n(()=>[...t[14]||(t[14]=[l("如果有誰的需求超出了 64 位計算機的極限，他一定沒有告訴別人",-1)])]),_:1}),t[16]||(t[16]=l("。",-1))]),t[37]||(t[37]=r("hr",null,null,-1)),r("p",null,[t[18]||(t[18]=l("via: ",-1)),i(o,{href:"https://theartofmachinery.com/2019/01/05/sorting_is_nlogn.html"},{default:n(()=>[...t[17]||(t[17]=[l("https://theartofmachinery.com/2019/01/05/sorting_is_nlogn.html",-1)])]),_:1})]),r("p",null,[t[23]||(t[23]=l("作者：",-1)),i(o,{href:"https://theartofmachinery.com"},{default:n(()=>[...t[19]||(t[19]=[l("Simon Arneaud",-1)])]),_:1}),t[24]||(t[24]=l(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[20]||(t[20]=[l("lujun9972",-1)])]),_:1}),t[25]||(t[25]=l(" 譯者：",-1)),i(o,{href:"https://github.com/silentdawn-zz"},{default:n(()=>[...t[21]||(t[21]=[l("silentdawn-zz",-1)])]),_:1}),t[26]||(t[26]=l(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[22]||(t[22]=[l("wxy",-1)])]),_:1})]),r("p",null,[t[29]||(t[29]=l("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[27]||(t[27]=[l("LCTT",-1)])]),_:1}),t[30]||(t[30]=l(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...t[28]||(t[28]=[l("Linux中國",-1)])]),_:1}),t[31]||(t[31]=l(" 榮譽推出",-1))])])}const h=e($,[["render",g]]);export{_ as __pageData,h as default};
